package com.app.bharatphoton.common//noinspection SuspiciousImportimport android.Rimport android.content.Contextimport android.widget.ArrayAdapterimport android.widget.Spinnerclass SpinnerHelper {    companion object{        fun spinner(context: Context, spinner: Spinner, statusList: List<String?>) {            val adapter = ArrayAdapter(context, R.layout.simple_spinner_item, statusList)            adapter.setDropDownViewResource(R.layout.simple_spinner_dropdown_item)            spinner.adapter = adapter        }    }}